        static float SignedDistance(Vector2[] path,Vector2 p) {
            bool inside=false;float distance=float.PositiveInfinity;
            for(int i=0;i<path.Length;i++) {
                Vector2 a=path[i],b=path[(i+1)%path.Length],edge=b-a;
                float t=Mathf.Clamp01(Vector2.Dot(p-a,edge)/Mathf.Max(1e-12f,edge.sqrMagnitude));distance=Mathf.Min(distance,Vector2.Distance(p,a+edge*t));
                if((a.y>p.y)!=(b.y>p.y))if(p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)inside=!inside;
            }
            return inside?-distance:distance;
        }
        public static float Coverage(int panel,Vector2 p) {
            float result=0;
            for(int island=0;island<FishFrontPaintGuides.BrushCount(panel);island++) {
                float outer=FishFrontPaintGuides.BrushCoverage(panel,island,p);if(outer<=0)continue;
                float core=float.PositiveInfinity;
                for(int i=0;i<Cores.Length;i++)if(Panels[i]==panel&&Islands[i]==island)core=Mathf.Min(core,SignedDistance(Cores[i],p));
                if(float.IsPositiveInfinity(core)){result=Mathf.Max(result,outer);continue;}
                float outerDistance=Mathf.Max(0,-FishFrontPaintGuides.BrushDistance(panel,island,p));
                float interior=core<=0?1:outerDistance/Mathf.Max(1e-9f,outerDistance+core);
                result=Mathf.Max(result,outer*Mathf.Lerp(.22f,1,Mathf.SmoothStep(0,1,interior)));
            }
            return result;
        }
